const cmd = `try { & dsh --version } catch { 'ERR ' + $_.Exception.Message }`;
const r = await tools.pwsh({ description: "Check dsh CLI version", command: cmd, timeoutMs: 60000 });
if (r.kind === "foreground") console.log("stdout:", r.stdout.text.slice(0, 500), "| stderr:", r.stderr.text.slice(0, 500));
